// Checks the request from the Angular app again on the server and finds the client IP address.
const UNITS = ['gram', 'kg', 'ml', 'l', 'piece'];
const COOKING_TIMES = ['quick', 'medium', 'complex'];
const CUISINES = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion', 'arabic'];
const DIETS = ['vegetarian', 'vegan', 'keto', 'none'];
const SERVINGS = { min: 1, max: 12 };
const COOKS = { min: 1, max: 3 };
const MAX_INGREDIENTS = 30;
const MAX_NAME_LENGTH = 60;
const MAX_AMOUNT = 100000;
// Letters of all languages, digits and a few punctuation marks; keeps prompt injection out.
const NAME_PATTERN = /^[\p{L}\p{N} .,'()&\/-]+$/u;
const IPV4 = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
const IPV6 = /^[0-9a-f:]+$/;
const UNKNOWN_IP = 'unknown';

const { body = {}, headers = {} } = $input.first().json;
const errors = [];

function isInRange(value, range) {
  return Number.isInteger(value) && value >= range.min && value <= range.max;
}

function isIpV6(value) {
  return value.includes(':') && value.length <= 39 && IPV6.test(value) && value.split('::').length <= 2;
}

// Behind a proxy the original address is the first entry of X-Forwarded-For.
function readClientIp() {
  const forwarded = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
  const raw = String(forwarded || headers['x-real-ip'] || '').trim().toLowerCase();
  if (!raw) {
    return UNKNOWN_IP;
  }
  const address = raw.replace(/^::ffff:(?=\d+\.)/, '');
  return IPV4.test(address) || isIpV6(address) ? address : null;
}

function cleanIngredient(entry, index) {
  const name = typeof entry?.name === 'string' ? entry.name.trim().replace(/\s+/g, ' ') : '';
  if (!name || name.length > MAX_NAME_LENGTH || !NAME_PATTERN.test(name)) {
    errors.push(`ingredients[${index}].name is missing or contains invalid characters`);
  }
  if (typeof entry?.amount !== 'number' || !(entry.amount > 0) || entry.amount > MAX_AMOUNT) {
    errors.push(`ingredients[${index}].amount must be a number between 0 and ${MAX_AMOUNT}`);
  }
  if (!UNITS.includes(entry?.unit)) {
    errors.push(`ingredients[${index}].unit must be one of ${UNITS.join(', ')}`);
  }
  return { name, amount: entry?.amount, unit: entry?.unit };
}

const rawIngredients = Array.isArray(body.ingredients) ? body.ingredients : [];
if (rawIngredients.length < 1 || rawIngredients.length > MAX_INGREDIENTS) {
  errors.push(`ingredients must contain 1 to ${MAX_INGREDIENTS} entries`);
}
const ingredients = rawIngredients.slice(0, MAX_INGREDIENTS).map(cleanIngredient);

if (!isInRange(body.servings, SERVINGS)) errors.push('servings must be a whole number from 1 to 12');
if (!isInRange(body.cooks, COOKS)) errors.push('cooks must be a whole number from 1 to 3');
if (!COOKING_TIMES.includes(body.cookingTime)) errors.push(`cookingTime must be one of ${COOKING_TIMES.join(', ')}`);
if (!CUISINES.includes(body.cuisine)) errors.push(`cuisine must be one of ${CUISINES.join(', ')}`);
if (!DIETS.includes(body.diet)) errors.push(`diet must be one of ${DIETS.join(', ')}`);

const ip = readClientIp();
if (!ip) errors.push('the client IP address is invalid');

console.log(`[recipe-generator] request from ${ip ?? 'invalid ip'}: ${errors.length} validation error(s)`);

return [{
  json: {
    isValid: errors.length === 0,
    errors,
    ip,
    request: {
      ingredients,
      servings: body.servings,
      cooks: body.cooks,
      cookingTime: body.cookingTime,
      cuisine: body.cuisine,
      diet: body.diet,
    },
  },
}];

// Daily limits as cost airbag: requests per IP address and recipes for the whole system.
// The counters live in the workflow's static data; they are only kept for production runs
// of the active workflow (not for manual test runs in the editor).
const REQUESTS_PER_IP = 3;
const SYSTEM_RECIPES_PER_DAY = 12;
const RECIPES_PER_REQUEST = 3;

const data = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (data.quotaDate !== today) {
  data.quotaDate = today;
  data.requestsByIp = {};
  data.recipesToday = 0;
}

const input = $input.first().json;
const usedByIp = data.requestsByIp[input.ip] || 0;
const hasIpQuota = usedByIp < REQUESTS_PER_IP;
const hasSystemQuota = data.recipesToday + RECIPES_PER_REQUEST <= SYSTEM_RECIPES_PER_DAY;

console.log(`[recipe-generator] quota ${input.ip}: ${usedByIp}/${REQUESTS_PER_IP}, system ${data.recipesToday}/${SYSTEM_RECIPES_PER_DAY}`);

return [{
  json: {
    ...input,
    isQuotaAvailable: hasIpQuota && hasSystemQuota,
    quotaReason: !hasIpQuota ? 'ip' : !hasSystemQuota ? 'system' : null,
    quota: { remaining: Math.max(0, REQUESTS_PER_IP - usedByIp), limit: REQUESTS_PER_IP },
  },
}];

// Prepares the AI agent: fixed rules and the answer format as system message,
// the user's input as prompt.
const { request } = $input.first().json;

const COOKING_TIME_RULES = {
  quick: 'at most 20 minutes in total',
  medium: 'between 20 and 45 minutes in total',
  complex: 'more than 45 minutes in total',
};
const DIET_RULES = {
  vegetarian: 'vegetarian: no meat, no fish, no seafood, no gelatine',
  vegan:
    'vegan: no animal products at all (no meat, fish, dairy, eggs, honey)',
  keto:
    'keto: at most 20 g carbohydrates per serving, ' +
    'no sugar, no grains, no potatoes',
  none: 'no dietary restriction',
};

// Example of the expected answer; the agent has to fill in real values.
const ANSWER_FORMAT = JSON.stringify({
  excludedIngredients: [{ name: 'Chicken', reason: 'contains meat' }],
  recipes: [
    {
      title: 'Recipe title',
      cookingTime: 20,
      ingredients: [
        { name: 'Pasta', amount: 160, unit: 'gram', isMissing: false },
      ],
      steps: [
        { number: '1', title: 'Step title', description: 'Text', chef: 1 },
      ],
      nutritionPerServing: { energy: 520, protein: 18, fat: 14, carbs: 70 },
    },
  ],
});

const SYSTEM = [
  'You are an experienced chef who writes recipes for home cooks ' +
    'and beginners. Write all texts in English.',
  'Create exactly 3 recipes that clearly differ in preparation method ' +
    'or flavour.',
  'Each recipe must use at least 70 % of the listed user ingredients; ' +
    'write their names exactly as listed and set isMissing to false.',
  'Each recipe may add at most 3 basic extra ingredients ' +
    '(e.g. oil, salt, garlic); set isMissing to true for them.',
  'First check every listed user ingredient against the diet. Never use ' +
    'one that conflicts with it; list it in excludedIngredients with its ' +
    'name exactly as listed and a short reason (e.g. "contains meat"). ' +
    'Leave excludedIngredients empty if all ingredients fit.',
  'The 70 % rule applies to the user ingredients that fit the diet.',
  'Scale all amounts to the number of servings. ' +
    'Use only the units gram, kg, ml, l and piece.',
  'Use spices, techniques and dishes typical for the requested cuisine.',
  'Split the work between the cooks: every step has a chef number from 1 ' +
    'to the number of cooks, and every cook gets steps.',
  'Order steps chronologically. Steps that run at the same time share ' +
    'their number with a letter, e.g. "2a" and "2b".',
  'Use waiting times (oven, simmering, resting) for other preparations ' +
    'and say so in the step.',
  'Describe every step clearly enough for beginners. cookingTime is the ' +
    'total time in minutes; nutritionPerServing holds kcal and grams ' +
    'per serving.',
  'Answer with one JSON object only: no markdown, no code fences, ' +
    'no text before or after it. Use exactly this structure:',
  ANSWER_FORMAT,
].join('\n');

const ingredientList = request.ingredients
  .map((entry) => `- ${entry.name}: ${entry.amount} ${entry.unit}`)
  .join('\n');

const prompt = [
  'Ingredients available at home:',
  ingredientList,
  '',
  `Servings: ${request.servings}`,
  `Number of cooks: ${request.cooks}`,
  `Cooking time: ${COOKING_TIME_RULES[request.cookingTime]}`,
  `Cuisine: ${request.cuisine}`,
  `Diet: ${DIET_RULES[request.diet]}`,
].join('\n');

return [{ json: { systemMessage: SYSTEM, prompt } }];

// Checks the agent's structured answer against the rules of the user stories
// before saving.
const MIN_USAGE = 0.7;
const MAX_MISSING = 3;
const UNITS = ['gram', 'kg', 'ml', 'l', 'piece'];
const TIME_RANGES = {
  quick: [1, 20],
  medium: [20, 45],
  complex: [46, 600],
};

const { request } = $('Check daily quota').first().json;
const problems = [];

// The agent answers with text. Markdown fences or words around the JSON
// are removed before parsing; an object is taken as it is.
function parseAnswer(output) {
  if (typeof output !== 'string') {
    return output ?? {};
  }
  const text = output.replace(/```(?:json)?/gi, '');
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  return JSON.parse(text.slice(start, end + 1));
}

let answer = {};
try {
  answer = parseAnswer($input.first().json.output);
} catch (error) {
  problems.push('the answer is not valid JSON');
}
const recipes = answer.recipes ?? [];

// Only user ingredients count as excluded;
// the agent cannot drop anything else this way.
const allUserNames = request.ingredients.map(
  (entry) => entry.name.toLowerCase(),
);
const excludedIngredients = (answer.excludedIngredients ?? [])
  .filter((entry) =>
    allUserNames.includes(String(entry.name).toLowerCase()),
  )
  .map((entry) => ({
    name: String(entry.name),
    reason: String(entry.reason ?? 'does not fit the diet'),
  }));
const excludedNames = excludedIngredients.map(
  (entry) => entry.name.toLowerCase(),
);
const userNames = allUserNames.filter(
  (name) => !excludedNames.includes(name),
);
if (userNames.length === 0) {
  problems.push('none of the ingredients fits the diet');
}

function namesMatch(name, userName) {
  return name.includes(userName) || userName.includes(name);
}

function isUserIngredient(name) {
  return userNames.some((userName) => namesMatch(name, userName));
}

// The flag is set again here, so it never depends on the model alone.
function markMissing(ingredient) {
  const name = String(ingredient.name ?? '').trim();
  const isMissing = !isUserIngredient(name.toLowerCase());
  return { ...ingredient, name, isMissing };
}

function countUsedUserIngredients(ingredients) {
  const ownNames = ingredients
    .filter((ingredient) => !ingredient.isMissing)
    .map((ingredient) => ingredient.name.toLowerCase());
  return userNames.filter((userName) =>
    ownNames.some((name) => namesMatch(name, userName)),
  ).length;
}

function hasInvalidAmount(ingredient) {
  return !UNITS.includes(ingredient.unit) || !(ingredient.amount > 0);
}

function checkRecipe(recipe, index) {
  const label = `recipe ${index + 1}`;
  const ingredients = (recipe.ingredients ?? []).map(markMissing);
  const missing = ingredients.filter((item) => item.isMissing).length;
  const usage = countUsedUserIngredients(ingredients) / userNames.length;
  const [minTime, maxTime] = TIME_RANGES[request.cookingTime];
  const time = recipe.cookingTime;
  const steps = recipe.steps ?? [];
  const chefs = new Set(steps.map((step) => step.chef));
  const isChefValid = (chef) => chef >= 1 && chef <= request.cooks;

  if (!recipe.title?.trim()) {
    problems.push(`${label}: title is missing`);
  }
  if (missing > MAX_MISSING) {
    problems.push(`${label}: ${missing} extra ingredients`);
  }
  if (usage < MIN_USAGE) {
    problems.push(`${label}: uses less than 70 % of the user ingredients`);
  }
  if (!(time >= minTime && time <= maxTime)) {
    problems.push(`${label}: cooking time does not fit the category`);
  }
  if (ingredients.some(hasInvalidAmount)) {
    problems.push(`${label}: invalid amount or unit`);
  }
  if (steps.length === 0) {
    problems.push(`${label}: no steps`);
  }
  if ([...chefs].some((chef) => !isChefValid(chef))) {
    problems.push(`${label}: step for an unknown cook`);
  }
  if (chefs.size !== request.cooks) {
    problems.push(`${label}: not every cook has steps`);
  }

  return {
    title: recipe.title?.trim(),
    cooking_time: time,
    cooking_time_category: request.cookingTime,
    cuisine: request.cuisine,
    diet: request.diet,
    servings: request.servings,
    cooks: request.cooks,
    ingredients,
    steps: steps.map((step) => ({ ...step, number: String(step.number) })),
    nutrition_per_serving: recipe.nutritionPerServing,
    likes: 0,
  };
}

if (recipes.length !== 3) {
  problems.push(`expected 3 recipes, got ${recipes.length}`);
}
const rows = recipes.map(checkRecipe);
const titles = new Set(rows.map((row) => row.title?.toLowerCase()));
if (titles.size !== rows.length) {
  problems.push('the recipes are not different');
}

console.log(
  `[recipe-generator] ${rows.length} recipe(s), ${problems.length} problem(s)`,
  problems,
);

return [
  {
    json: {
      isValid: problems.length === 0,
      problems,
      rows,
      excludedIngredients,
    },
  },
];

// Counts the successful request against both daily limits and builds the answer for the app.
const RECIPES_PER_REQUEST = 3;

const { ip, quota } = $('Check daily quota').first().json;
const { excludedIngredients } = $('Check generated recipes').first().json;
const data = $getWorkflowStaticData('global');
data.requestsByIp[ip] = (data.requestsByIp[ip] || 0) + 1;
data.recipesToday += RECIPES_PER_REQUEST;

const recipes = $input.all().map(({ json: row }) => ({
  id: row.id,
  title: row.title,
  cookingTime: row.cooking_time,
  cookingTimeCategory: row.cooking_time_category,
  cuisine: row.cuisine,
  diet: row.diet,
  servings: row.servings,
  cooks: row.cooks,
  ingredients: row.ingredients,
  steps: row.steps,
  nutritionPerServing: row.nutrition_per_serving,
  likes: row.likes,
}));

console.log(`[recipe-generator] saved ${recipes.length} recipe(s) for ${ip}`);

return [{
  json: {
    recipes,
    excludedIngredients,
    quota: { remaining: Math.max(0, quota.remaining - 1), limit: quota.limit },
  },
}];
